<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap.php';require_once __DIR__.'/admin-ui.php';require_once __DIR__.'/blog-lib.php';$user=require_admin();require_capability($user,'categories');$db=blog_db();$id=(int)($_GET['id']??0);$error='';$c=['name'=>'','slug'=>'','description'=>'','meta_title'=>'','meta_description'=>'','status'=>'active'];if($id){$q=$db->prepare('SELECT * FROM categories WHERE id=?');$q->execute([$id]);$c=$q->fetch()?:$c;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);$c=['name'=>clean_text($_POST['name']??'',120),'slug'=>admin_slug($_POST['slug']?:$_POST['name']??''),'description'=>clean_text($_POST['description']??'',5000),'meta_title'=>clean_text($_POST['meta_title']??'',255),'meta_description'=>clean_text($_POST['meta_description']??'',320),'status'=>in_array($_POST['status']??'', ['active','inactive'],true)?$_POST['status']:'active'];if(!$c['name'])$error='Category name is required.';$q=$db->prepare('SELECT id FROM categories WHERE slug=? AND id!=?');$q->execute([$c['slug'],$id]);if(!$error&&$q->fetch())$error='That slug is already in use.';if(!$error){if($id){$db->prepare('UPDATE categories SET name=?,slug=?,description=?,meta_title=?,meta_description=?,status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute([...array_values($c),$id]);audit($db,$user,'update','category',$id,['slug'=>$c['slug']]);}else{$db->prepare('INSERT INTO categories(name,slug,description,meta_title,meta_description,status) VALUES(?,?,?,?,?,?)')->execute(array_values($c));$id=(int)$db->lastInsertId();audit($db,$user,'create','category',$id,['slug'=>$c['slug']]);}header('Location: /admin/categories.php');exit;}}
admin_layout_start($id?'Edit category':'Add category','categories',$user);?><div class="bar"><div><h1><?=$id?'Edit category':'Add category'?></h1><p>Inactive categories remain attached to existing posts but cannot be selected for new posts.</p></div><a class="btn alt" href="/admin/categories.php">Back to categories</a></div><?php if($error):?><p class="notice" style="background:#fff0f0;color:#8b1e1e"><?=htmlspecialchars($error)?></p><?php endif?><form method="post" class="grid"><section class="card"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Name</label><input name="name" maxlength="120" required value="<?=htmlspecialchars($c['name'])?>"><label>Slug</label><input name="slug" maxlength="160" value="<?=htmlspecialchars($c['slug'])?>"><label>Description</label><textarea name="description"><?=htmlspecialchars($c['description'])?></textarea></section><aside class="card"><h2>SEO</h2><label>Meta title</label><input name="meta_title" maxlength="255" value="<?=htmlspecialchars($c['meta_title'])?>"><label>Meta description</label><textarea name="meta_description" maxlength="320" style="min-height:100px"><?=htmlspecialchars($c['meta_description'])?></textarea><label>Status</label><select name="status"><option value="active" <?=$c['status']==='active'?'selected':''?>>Active</option><option value="inactive" <?=$c['status']==='inactive'?'selected':''?>>Inactive</option></select><button class="btn" style="margin-top:22px">Save category</button></aside></form><?php admin_layout_end();
